<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //m_rear++;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //队尾指针向后走，本行和上一行可以合并写成一行代码：m_data[m_rear++] = e;</span></span>
